\subsection{Definitions and mathematical statement}
\paragraph{Shared notation.}$\mathbb N$, $\mathbb Z$, $\mathbb Q$, $\mathbb R$, and $\mathbb C$ denote the natural numbers, integers, rationals, reals, and complex numbers, respectively. All additional parameters and hypotheses are specified in the question.


\paragraph{Statement recorded in the supplied source.}
Let $H<G$ be subgroups of a finite $p$-group and let $m,n$ be nonnegative integers. For which pairs $(m,n)$ does $$K(m)_*(\Phi^H X)=0\quad\Longrightarrow\quad K(n)_*(\Phi^G X)=0$$ hold for every finite $G$-spectrum $X$?
\par\smallskip\textit{Formulation references:} \href{https://huggingface.co/datasets/ulamai/UnsolvedMath}{[S1]}, \href{https://doi.org/10.4171/owr/2019/36}{[S2]}.

\subsection{Short English statement}
Let $H<G$ be subgroups of a finite $p$-group and let $m,n$ be nonnegative integers. For which pairs $(m,n)$ does $$K(m)_*(\Phi^H X)=0\quad\Longrightarrow\quad K(n)_*(\Phi^G X)=0$$ hold for every finite $G$-spectrum $X$?

\subsection{Sources}
\begin{itemize}
\item[S1] ULAM.AI and the UnsolvedMath Contributors, UnsolvedMath: A Curated Collection of Open Mathematics Problems, record 30004201 (OWR-17132-006). Catalogue attribution under CC BY 4.0.
\url{https://huggingface.co/datasets/ulamai/UnsolvedMath}.
\item[S2] Original problem formulation and mathematical context.
\url{https://doi.org/10.4171/owr/2019/36}.
\end{itemize}
\label{end:30004201}

